--
-- Table structure for table `app_users`
--

DROP TABLE IF EXISTS `app_users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `app_users` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `display_name` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `phone` varchar(255) DEFAULT NULL,
  `password` varchar(255) NOT NULL,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `phone_verified_at` timestamp NULL DEFAULT NULL,
  `birthdate` date NOT NULL,
  `gender` enum('woman','man','non_binary','other') NOT NULL,
  `pronouns` varchar(255) DEFAULT NULL,
  `city_id` bigint(20) unsigned DEFAULT NULL,
  `country_id` bigint(20) unsigned DEFAULT NULL,
  `last_latitude` decimal(10,7) DEFAULT NULL,
  `last_longitude` decimal(10,7) DEFAULT NULL,
  `account_status` enum('active','pending','limited','shadow_banned','suspended','banned','deactivated') NOT NULL DEFAULT 'pending',
  `verification_status` enum('unverified','pending','in_review','approved','rejected','escalated','expired') NOT NULL DEFAULT 'unverified',
  `is_premium` tinyint(1) NOT NULL DEFAULT 0,
  `premium_tier` varchar(40) DEFAULT NULL,
  `premium_until` timestamp NULL DEFAULT NULL,
  `signup_source` enum('ios','android','web') NOT NULL DEFAULT 'ios',
  `referred_by_id` bigint(20) unsigned DEFAULT NULL,
  `profile_completion` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `shadow_banned_until` timestamp NULL DEFAULT NULL,
  `suspended_until` timestamp NULL DEFAULT NULL,
  `banned_at` timestamp NULL DEFAULT NULL,
  `active_ban_id` bigint(20) unsigned DEFAULT NULL,
  `risk_score` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `risk_band` enum('low','elevated','high','critical') NOT NULL DEFAULT 'low',
  `risk_calculated_at` timestamp NULL DEFAULT NULL,
  `profile_completed_at` timestamp NULL DEFAULT NULL,
  `verified_at` timestamp NULL DEFAULT NULL,
  `first_swipe_at` timestamp NULL DEFAULT NULL,
  `first_match_at` timestamp NULL DEFAULT NULL,
  `first_message_at` timestamp NULL DEFAULT NULL,
  `first_reply_at` timestamp NULL DEFAULT NULL,
  `last_active_at` timestamp NULL DEFAULT NULL,
  `remember_token` varchar(100) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `app_users_uuid_unique` (`uuid`),
  UNIQUE KEY `app_users_email_unique` (`email`),
  UNIQUE KEY `app_users_phone_unique` (`phone`),
  KEY `app_users_country_id_foreign` (`country_id`),
  KEY `app_users_referred_by_id_foreign` (`referred_by_id`),
  KEY `app_users_account_status_index` (`account_status`),
  KEY `app_users_verification_status_index` (`verification_status`),
  KEY `app_users_risk_band_risk_score_index` (`risk_band`,`risk_score`),
  KEY `app_users_city_id_index` (`city_id`),
  KEY `app_users_last_active_at_index` (`last_active_at`),
  KEY `app_users_created_at_index` (`created_at`),
  KEY `app_users_gender_index` (`gender`),
  KEY `app_users_account_status_created_at_index` (`account_status`,`created_at`),
  KEY `app_users_birthdate_index` (`birthdate`),
  KEY `app_users_premium_until_index` (`premium_until`),
  KEY `app_users_is_premium_index` (`is_premium`),
  KEY `app_users_coordinates_index` (`last_latitude`,`last_longitude`),
  CONSTRAINT `app_users_city_id_foreign` FOREIGN KEY (`city_id`) REFERENCES `cities` (`id`) ON DELETE SET NULL,
  CONSTRAINT `app_users_country_id_foreign` FOREIGN KEY (`country_id`) REFERENCES `countries` (`id`) ON DELETE SET NULL,
  CONSTRAINT `app_users_referred_by_id_foreign` FOREIGN KEY (`referred_by_id`) REFERENCES `app_users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=81 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

