DROP TABLE IF EXISTS `appeals`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `appeals` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `app_user_id` bigint(20) unsigned NOT NULL,
  `ban_id` bigint(20) unsigned DEFAULT NULL,
  `moderation_action_id` bigint(20) unsigned DEFAULT NULL,
  `original_decider_id` bigint(20) unsigned DEFAULT NULL,
  `assigned_to_id` bigint(20) unsigned DEFAULT NULL,
  `status` enum('new','assigned','in_review','upheld','overturned','partially_overturned','withdrawn') NOT NULL DEFAULT 'new',
  `user_statement` text DEFAULT NULL,
  `decision_note` text DEFAULT NULL,
  `decided_at` timestamp NULL DEFAULT NULL,
  `sla_due_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `appeals_uuid_unique` (`uuid`),
  KEY `appeals_app_user_id_foreign` (`app_user_id`),
  KEY `appeals_ban_id_foreign` (`ban_id`),
  KEY `appeals_moderation_action_id_foreign` (`moderation_action_id`),
  KEY `appeals_original_decider_id_foreign` (`original_decider_id`),
  KEY `appeals_status_index` (`status`),
  KEY `appeals_assigned_to_id_index` (`assigned_to_id`),
  KEY `appeals_sla_due_at_index` (`sla_due_at`),
  CONSTRAINT `appeals_app_user_id_foreign` FOREIGN KEY (`app_user_id`) REFERENCES `app_users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `appeals_assigned_to_id_foreign` FOREIGN KEY (`assigned_to_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `appeals_ban_id_foreign` FOREIGN KEY (`ban_id`) REFERENCES `bans` (`id`) ON DELETE SET NULL,
  CONSTRAINT `appeals_moderation_action_id_foreign` FOREIGN KEY (`moderation_action_id`) REFERENCES `moderation_actions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `appeals_original_decider_id_foreign` FOREIGN KEY (`original_decider_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

