INSERT INTO `notification_templates` VALUES (1,'match.new','New match','member','push','engagement','You matched with {{ name }}','You and {{ name }} liked each other. Say hello.','[\"name\"]',0,1,NULL,'2026-09-26 12:13:31','2026-09-26 12:13:31'),(2,'message.new','New message','member','push','engagement','{{ name }} sent you a message','{{ name }}: {{ preview }}','[\"name\",\"preview\"]',0,1,NULL,'2026-09-26 12:13:31','2026-09-26 12:13:31'),(3,'match.silent_nudge','Silent match nudge','member','push','engagement','You matched with {{ name }} {{ elapsed }} ago','Neither of you has said anything yet. Someone has to go first.','[\"name\",\"elapsed\"]',0,1,NULL,'2026-09-26 12:13:31','2026-09-26 12:13:31'),(4,'likes.waiting','Likes waiting','member','push','engagement','{{ count }} people liked you','Open the app to see who.','[\"count\"]',0,1,NULL,'2026-09-26 12:13:31','2026-09-26 12:13:31'),(5,'profile.incomplete','Incomplete profile','member','push','onboarding','Your profile is {{ completion }}% complete','Profiles with photos and a bio get far more matches. It takes two minutes.','[\"completion\"]',0,1,NULL,'2026-09-26 12:13:31','2026-09-26 12:13:31'),(6,'verification.prompt','Verification prompt','member','push','onboarding','Get verified','Verified profiles get noticeably more matches, and it takes about a minute.','[]',0,1,NULL,'2026-09-26 12:13:31','2026-09-26 12:13:31'),(7,'verification.approved','Verification approved','member','push','verification','You are verified','Your photo verification was approved. Your profile now carries a verified badge.','[]',1,1,NULL,'2026-09-26 12:13:31','2026-09-26 12:13:31'),(8,'verification.rejected','Verification rejected','member','push','verification','We could not verify your photo','We could not verify your submission: {{ reason }}.\n\nYou have {{ attempts_remaining }} attempts remaining.','[\"reason\",\"attempts_remaining\"]',1,1,NULL,'2026-09-26 12:13:31','2026-09-26 12:13:31'),(9,'appeal.received','Appeal received','member','push','appeals','We received your appeal','A different member of our team will review it. We aim to respond within {{ sla_hours }} hours.','[\"sla_hours\"]',1,1,NULL,'2026-09-26 12:13:31','2026-09-26 12:13:31'),(10,'appeal.decided','Appeal decided','member','push','appeals','Your appeal has been reviewed','{{ outcome }}\n\n{{ reasoning }}','[\"outcome\",\"reasoning\"]',1,1,NULL,'2026-09-26 12:13:31','2026-09-26 12:13:31'),(11,'billing.renewal_push','Plan ending soon (push)','member','push','billing','{{ plan_name }} ends in {{ days_left }} days','Renew before {{ end_date }} to keep {{ plan_name }}.','[\"first_name\",\"plan_name\",\"days_left\",\"end_date\"]',1,1,NULL,'2026-09-26 12:13:31','2026-09-26 12:13:31'),(12,'billing.renewal_email','Plan ending soon (email)','member','email','billing','Your {{ plan_name }} ends in {{ days_left }} days','Hi {{ first_name }},\n\nYour {{ plan_name }} plan ends on {{ end_date }}.\n\nRenew before then to keep unlimited likes and everything else your plan includes. Nothing else about your account changes, and your matches and messages stay exactly as they are.','[\"first_name\",\"plan_name\",\"days_left\",\"end_date\"]',1,1,NULL,'2026-09-26 12:13:31','2026-09-26 12:13:31'),(13,'billing.expired','Plan ended','member','email','billing','Your {{ plan_name }} has ended','Hi {{ first_name }},\n\nYour {{ plan_name }} plan ended today, so your account is back on the free tier.\n\nYour profile, matches and messages are all still here. You can start a plan again whenever you like.','[\"first_name\",\"plan_name\"]',1,1,NULL,'2026-09-26 12:13:31','2026-09-26 12:13:31'),(14,'billing.plan_started','Plan started','member','email','billing','Your {{ plan_name }} is active','Hi {{ first_name }},\n\n{{ plan_name }} is now active on your account{{ until_clause }}.\n\nEverything it unlocks is available straight away.','[\"first_name\",\"plan_name\",\"until_clause\"]',1,1,NULL,'2026-09-26 12:13:31','2026-09-26 12:13:31'),(15,'enforcement.harassment_confirmed','Enforcement — Harassment confirmed','member','in_app','enforcement','Action has been taken on your account','We reviewed activity on your account and found it did not meet our harassment confirmed policy (4.2 Respectful conduct).\n\nPolicy clause: 4.2 Respectful conduct.\n\nThis decision was made by {{ decided_by }}.\n\nIf you believe this is wrong, you can appeal within {{ appeal_window_days }} days.','[\"decided_by\",\"appeal_window_days\"]',1,1,NULL,'2026-09-26 12:13:31','2026-09-26 12:13:31'),(16,'enforcement.hate_speech_confirmed','Enforcement — Hate speech confirmed','member','in_app','enforcement','Action has been taken on your account','We reviewed activity on your account and found it did not meet our hate speech confirmed policy (4.2 Respectful conduct).\n\nPolicy clause: 4.2 Respectful conduct.\n\nThis decision was made by {{ decided_by }}.\n\nIf you believe this is wrong, you can appeal within {{ appeal_window_days }} days.','[\"decided_by\",\"appeal_window_days\"]',1,1,NULL,'2026-09-26 12:13:31','2026-09-26 12:13:31'),(17,'enforcement.threat_of_violence','Enforcement — Threat of violence','member','in_app','enforcement','Action has been taken on your account','We reviewed activity on your account and found it did not meet our threat of violence policy (4.2 Respectful conduct).\n\nPolicy clause: 4.2 Respectful conduct.\n\nThis decision was made by {{ decided_by }}.\n\nIf you believe this is wrong, you can appeal within {{ appeal_window_days }} days.','[\"decided_by\",\"appeal_window_days\"]',1,1,NULL,'2026-09-26 12:13:31','2026-09-26 12:13:31'),(18,'enforcement.unsolicited_sexual_content','Enforcement — Unsolicited sexual content','member','in_app','enforcement','Action has been taken on your account','We reviewed activity on your account and found it did not meet our unsolicited sexual content policy (4.3 Sexual content).\n\nPolicy clause: 4.3 Sexual content.\n\nThis decision was made by {{ decided_by }}.\n\nIf you believe this is wrong, you can appeal within {{ appeal_window_days }} days.','[\"decided_by\",\"appeal_window_days\"]',1,1,NULL,'2026-09-26 12:13:31','2026-09-26 12:13:31'),(19,'enforcement.prohibited_nudity','Enforcement — Prohibited nudity','member','in_app','enforcement','Action has been taken on your account','We reviewed activity on your account and found it did not meet our prohibited nudity policy (4.3 Sexual content).\n\nPolicy clause: 4.3 Sexual content.\n\nThis decision was made by {{ decided_by }}.\n\nIf you believe this is wrong, you can appeal within {{ appeal_window_days }} days.','[\"decided_by\",\"appeal_window_days\"]',1,1,NULL,'2026-09-26 12:13:31','2026-09-26 12:13:31'),(20,'enforcement.fake_profile_confirmed','Enforcement — Fake profile confirmed','member','in_app','enforcement','Action has been taken on your account','We reviewed activity on your account and found it did not meet our fake profile confirmed policy (3.1 Authentic identity).\n\nPolicy clause: 3.1 Authentic identity.\n\nThis decision was made by {{ decided_by }}.\n\nIf you believe this is wrong, you can appeal within {{ appeal_window_days }} days.','[\"decided_by\",\"appeal_window_days\"]',1,1,NULL,'2026-09-26 12:13:31','2026-09-26 12:13:31'),(21,'enforcement.impersonation_confirmed','Enforcement — Impersonation confirmed','member','in_app','enforcement','Action has been taken on your account','We reviewed activity on your account and found it did not meet our impersonation confirmed policy (3.1 Authentic identity).\n\nPolicy clause: 3.1 Authentic identity.\n\nThis decision was made by {{ decided_by }}.\n\nIf you believe this is wrong, you can appeal within {{ appeal_window_days }} days.','[\"decided_by\",\"appeal_window_days\"]',1,1,NULL,'2026-09-26 12:13:31','2026-09-26 12:13:31'),(22,'enforcement.stolen_photos','Enforcement — Photos taken from another person','member','in_app','enforcement','Action has been taken on your account','We reviewed activity on your account and found it did not meet our ph