--
-- Table structure for table `profiles`
--

DROP TABLE IF EXISTS `profiles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `profiles` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `app_user_id` bigint(20) unsigned NOT NULL,
  `bio` text DEFAULT NULL,
  `height_cm` smallint(5) unsigned DEFAULT NULL,
  `job_title` varchar(255) DEFAULT NULL,
  `company` varchar(255) DEFAULT NULL,
  `school` varchar(255) DEFAULT NULL,
  `education` varchar(255) DEFAULT NULL,
  `relationship_goal` enum('long_term','short_term','friends','figuring_out','unspecified') NOT NULL DEFAULT 'unspecified',
  `drinking` enum('never','socially','often','unspecified') NOT NULL DEFAULT 'unspecified',
  `smoking` enum('never','socially','often','unspecified') NOT NULL DEFAULT 'unspecified',
  `children` enum('have','want','dont_want','unspecified') NOT NULL DEFAULT 'unspecified',
  `religion` varchar(255) DEFAULT NULL,
  `politics` varchar(255) DEFAULT NULL,
  `languages` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`languages`)),
  `prompts` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`prompts`)),
  `bio_contains_contact` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `profiles_app_user_id_unique` (`app_user_id`),
  CONSTRAINT `profiles_app_user_id_foreign` FOREIGN KEY (`app_user_id`) REFERENCES `app_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=81 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

