--
-- Table structure for table `verifications`
--

DROP TABLE IF EXISTS `verifications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `verifications` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `app_user_id` bigint(20) unsigned NOT NULL,
  `attempt_no` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `type` enum('selfie','id_document','phone') NOT NULL DEFAULT 'selfie',
  `status` enum('pending','in_review','approved','rejected','escalated','expired') NOT NULL DEFAULT 'pending',
  `queue` enum('standard','restricted_minor','appeal') NOT NULL DEFAULT 'standard',
  `selfie_disk` varchar(255) NOT NULL DEFAULT 'verifications',
  `selfie_path` varchar(255) DEFAULT NULL,
  `gesture_code` varchar(8) DEFAULT NULL,
  `face_match_score` decimal(4,3) DEFAULT NULL,
  `liveness_passed` tinyint(1) NOT NULL DEFAULT 0,
  `liveness_score` decimal(4,3) DEFAULT NULL,
  `duplicate_face_account_count` smallint(5) unsigned NOT NULL DEFAULT 0,
  `device_reuse_count` smallint(5) unsigned NOT NULL DEFAULT 0,
  `estimated_age_min` tinyint(3) unsigned DEFAULT NULL,
  `estimated_age_max` tinyint(3) unsigned DEFAULT NULL,
  `minor_suspected` tinyint(1) NOT NULL DEFAULT 0,
  `claimed_by` bigint(20) unsigned DEFAULT NULL,
  `claimed_at` timestamp NULL DEFAULT NULL,
  `reviewed_by` bigint(20) unsigned DEFAULT NULL,
  `reviewed_at` timestamp NULL DEFAULT NULL,
  `rejection_reason_code` varchar(255) DEFAULT NULL,
  `internal_note` text DEFAULT NULL,
  `submitted_at` datetime NOT NULL,
  `sla_due_at` datetime NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `verifications_uuid_unique` (`uuid`),
  KEY `verifications_claimed_by_foreign` (`claimed_by`),
  KEY `verifications_reviewed_by_foreign` (`reviewed_by`),
  KEY `verifications_status_queue_index` (`status`,`queue`),
  KEY `verifications_sla_due_at_index` (`sla_due_at`),
  KEY `verifications_app_user_id_index` (`app_user_id`),
  KEY `verifications_minor_suspected_index` (`minor_suspected`),
  CONSTRAINT `verifications_app_user_id_foreign` FOREIGN KEY (`app_user_id`) REFERENCES `app_users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `verifications_claimed_by_foreign` FOREIGN KEY (`claimed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `verifications_reviewed_by_foreign` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

